parameters.text:
=Student Name: {{ $('On form submission').item.json['Student Name'] }}
Bio: {{ $('On form submission').item.json['Student Bio / Profile'] }}
Looking for: {{ $('On form submission').item.json['Looking for'] }}

Based on this profile, return ONLY this JSON, no backticks:
{
  "summary": "2 sentence summary of who this student is",
  "strengths": "their top 3 skills or qualities",
  "ideal_connections": "who they should connect with and why",
  "icebreaker": "a warm intro message they could send to a potential connection",
  "tags": "3-5 hashtag labels like #AIBuilder #Founder #Chennai"
}

parameters.jsCode:
const raw = $input.first().json.text;

// Strip markdown code fences
const cleaned = raw.replace(/```json\n?/g, '').replace(/```/g, '').trim();

const parsed = JSON.parse(cleaned);

return [{
  json: {
    summary: parsed.summary,
    strengths: parsed.strengths,
    ideal_connections: parsed.ideal_connections,
    icebreaker: parsed.icebreaker,
    tags: parsed.tags
  }
}];
